import{_ as o,o as t,c as r,a2 as a}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"JipperKeyViewer","description":"","frontmatter":{"title":"JipperKeyViewer","order":5},"headers":[],"relativePath":"mods/jipperkeyviewer.md","filePath":"mods/jipperkeyviewer.md","lastUpdated":1786957039000}'),i={name:"mods/jipperkeyviewer.md"};function n(l,e,s,d,p,h){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="jipperkeyviewer" tabindex="-1">JipperKeyViewer <a class="header-anchor" href="#jipperkeyviewer" aria-label="Permalink to &quot;JipperKeyViewer&quot;">​</a></h1><blockquote><p>An ADOFAI <strong>key viewer</strong> Mod: real-time key press display, KPS stats, and raindrop effects. Supports <strong>UnityModManager</strong> and <strong>MelonLoader</strong>, with UI in Chinese / English / Korean.</p><p>Project: <a href="https://github.com/adofaiex/JipperKeyViewer" target="_blank" rel="noreferrer">https://github.com/adofaiex/JipperKeyViewer</a></p></blockquote><h2 id="versions" tabindex="-1">Versions <a class="header-anchor" href="#versions" aria-label="Permalink to &quot;Versions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Version</th><th>Description</th></tr></thead><tbody><tr><td><strong>JipperKeyViewer</strong></td><td>Standard version, loads resources from <code>keyviewer_resources</code> AssetBundle</td></tr><tr><td><strong>JipperKeyViewer-FileBased</strong></td><td>Loads images/fonts directly from PNG/OTF files, no AssetBundle needed</td></tr></tbody></table><p>Both versions have identical functionality and support UMM and MelonLoader.</p><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><ul><li><strong>Layouts</strong>: 8K / 10K / 12K / 14K / 16K / 20K / 24K, and full <strong>108-key</strong> physical keyboard, foot pedal 2K–16K</li><li>KPS stats and total key count, independent KPS per key</li><li><strong>Raindrop effects</strong>: smooth fade-out on key release; <strong>ghost key raindrops</strong> trigger raindrops only without showing the key</li><li>Independent raindrop control per row (speed, height, on/off)</li><li>Independent color per key, auto-rainbow KV; independent KPS / Total colors</li><li><strong>Standard key widths</strong>: mixed wide/narrow rows unified to 50px</li><li><strong>108-key full keyboard</strong>: complete QWERTY + numpad, movable as a block</li><li>KPS/Total text centered (auto-rearranges as numbers grow)</li><li>Streaming mode (hide KPS/Total), thousand-separator formatting</li><li>Font styles (bold/italic/underline), custom fonts (put <code>.ttf/.otf</code> in <code>CustomFont/</code> for auto-detection)</li><li>Normalized custom position (0–1), auto-adapts to any resolution</li><li>Key binding changes and custom text labels</li><li>Object pooling and merged rendering, zero GC allocation in hot paths</li></ul><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><h3 id="unity-mod-manager" tabindex="-1">Unity Mod Manager <a class="header-anchor" href="#unity-mod-manager" aria-label="Permalink to &quot;Unity Mod Manager&quot;">​</a></h3><ol><li>Install <a href="https://www.nexusmods.com/site/mods/21" target="_blank" rel="noreferrer">UMM</a></li><li>Download the <strong>UMM</strong> version from <a href="https://github.com/adofaiex/JipperKeyViewer/releases" target="_blank" rel="noreferrer">Releases</a></li><li>Install via UMM, or extract to <code>ADOFAI/Mods/JipperKeyViewer/</code></li></ol><h3 id="melonloader" tabindex="-1">MelonLoader <a class="header-anchor" href="#melonloader" aria-label="Permalink to &quot;MelonLoader&quot;">​</a></h3><ol><li>Install <a href="https://melonwiki.xyz/" target="_blank" rel="noreferrer">MelonLoader</a></li><li>Download the <strong>MelonLoader</strong> version from Releases</li><li>Extract to <code>ADOFAI/Mods/JipperKeyViewer-melon/</code></li><li>Press <strong>F7</strong> in-game to open settings (rebindable)</li></ol><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><blockquote><p>📝 To be supplemented (feel free to report in the repository Issues)</p></blockquote>',14)])])}const g=o(i,[["render",n]]);export{u as __pageData,g as default};
